local SnugUI = _G.SnugUI

local moduleName = "profiles"

local function makeSettings()
    SnugUI.api.generateSettingsUI(moduleName, "Profiles", {
        title = "Profiles",
        message = "",
        subButtons = {
            { id="details",  title="Details!", message  = "Use the string below to import the SnugUI profile for Details!"},
            { id="suf",      title="Shadowed Unit Frames", message = "Use the string below to import the SnugUI profile for Shadowed Unit Frames!"},
            { id="weakauras", title="WeakAuras", message = "Use the string below to import the SnugUI profile for WeakAuras!"},
        }
    })
    SnugUI.api.addSetting(moduleName, "detailsExportBlock", "profileExport", {
        panel = "details",
        exportString = Details_Profile,
    })
    SnugUI.api.addSetting(moduleName, "sufExportBlock", "profileExport", {
        panel = "suf",
        exportString = SUF_Profile,
    })
    SnugUI.api.addSetting(moduleName, "WAExportBlock", "profileExport", {
        panel = "weakauras",
        exportString = WeakAuras_export,
    })
    SnugUI.api.renderSettings(moduleName)
end

SnugUI.loginTrigger(function()
    makeSettings()
end)





